import std.io
import std.process

pub fn main() effect io -> Result<(), process.ProcessError> {
    match process.run("/bin/sh", ["-c", "kill -9 $$"]) {
        Ok(pr) => {
            if pr.exitCode == 137 {
                io.println("sig-ok")
            } else {
                io.println("sig-bad ${pr.exitCode}")
            }
        }
        Err(_) => { io.println("spawn-failed") }
    }
    return Ok(())
}
